/* eslint-disable */
/// <reference lib="webworker" />

// Manut service worker.
//
// This is an internal business application, so the governing rule is:
// CACHE THE SHELL, NEVER THE DATA. Offline capability is worth having, but not
// at the cost of leaving HR, payroll, expense, CRM or messaging responses
// sitting in a cache on a shared or lost device. Every decision below follows
// from that.
//
// Hand-written rather than generated by next-pwa or serwist. Those libraries
// exist mainly to produce a precache manifest and apply runtime-caching
// recipes; here we deliberately precache almost nothing, and their default
// recipes — which happily cache API GETs — are precisely what must not happen.
// Next's static output is content-hashed, so it can be runtime-cached with no
// build manifest at all.
//
// WEB PUSH: added in Phase 6, at the bottom of this file. The caching rules
// above were not touched — push is additive, and the fetch handler's boundaries
// still apply exactly as before.

/**
 * Bump on release. Old caches are deleted on activate once the new worker takes
 * over, so a bump is how a bad cache gets cleared in the field.
 *
 * `/_next/static/*` URLs are content-hashed, so a stale entry is never *wrong* —
 * this version exists to garbage-collect and to give us a kill switch.
 */
const SW_VERSION = "v1";

const STATIC_CACHE = `tbh-static-${SW_VERSION}`;
const SHELL_CACHE = `tbh-shell-${SW_VERSION}`;
const CURRENT_CACHES = [STATIC_CACHE, SHELL_CACHE];

/** The offline document, plus the assets it needs to render standalone. */
const OFFLINE_URL = "/offline";
const SHELL_ASSETS = [
  OFFLINE_URL,
  "/manifest.webmanifest",
  "/icons/icon-192.png",
];

/* ── Install ──────────────────────────────────────────────────────────
   Precache only the offline fallback. No application routes: every one of
   them renders authenticated content, and a cached authenticated document is
   exactly the leak this worker is written to avoid.                       */

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Individually, so one 404 during a partial deploy cannot fail the whole
      // install and leave the app with no worker at all.
      await Promise.allSettled(
        SHELL_ASSETS.map((url) =>
          cache.add(new Request(url, { cache: "reload" })),
        ),
      );
      // NOTE: no skipWaiting() here. Taking over immediately would swap the
      // asset set under a page that is mid-workflow — someone half-way through
      // a leave request would get a broken screen. The new worker waits until
      // the client asks (see the message handler) or every tab closes.
    })(),
  );
});

/* ── Activate ─────────────────────────────────────────────────────────
   Clean up only after this worker is actually in charge, so a failed
   activation cannot leave the app with neither the old nor the new cache. */

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          // Scoped to our own prefix: another tool's cache on this origin is
          // not ours to delete.
          .filter((n) => n.startsWith("tbh-") && !CURRENT_CACHES.includes(n))
          .map((n) => caches.delete(n)),
      );
      await self.clients.claim();
    })(),
  );
});

/* ── Update handshake ─────────────────────────────────────────────── */

self.addEventListener("message", (event) => {
  // Only accept messages from same-origin controlled clients (defence in depth
  // — CodeQL js/missing-origin-check). event.origin is "" for some same-origin
  // client posts, so allow empty or an exact origin match.
  if (event.origin && event.origin !== self.location.origin) return;
  // Sent by the client when the user accepts the update prompt.
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
  // Lets the page ask which version is serving it, for diagnostics.
  if (event.data && event.data.type === "GET_VERSION") {
    event.source?.postMessage({ type: "VERSION", version: SW_VERSION });
  }
});

/* ── Fetch ────────────────────────────────────────────────────────────

   Four rules, in order:

     1. Anything that is not a same-origin GET is not touched at all.
     2. `/api/*` and auth paths are never cached, never intercepted.
     3. Content-hashed static assets: cache-first.
     4. Navigations: network-first, falling back to the offline page.

   Everything else falls through to the network with no service worker
   involvement, which is the safe default.                                */

/** Immutable, content-addressed, and safe to keep. */
function isHashedStatic(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/icons/") ||
    url.pathname === "/manifest.webmanifest" ||
    url.pathname === "/favicon.ico"
  );
}

/**
 * Paths this worker must never store, even for a moment.
 *
 * `/api/` covers every authenticated payload, because the browser talks to the
 * Express API through a same-origin rewrite. `/ingest/` is the PostHog proxy —
 * analytics must not be replayed from cache.
 */
function isNeverCacheable(url) {
  return (
    url.pathname.startsWith("/api/") ||
    url.pathname.startsWith("/ingest/") ||
    url.pathname.startsWith("/auth/")
  );
}

self.addEventListener("fetch", (event) => {
  const request = event.request;

  // Rule 1 — mutations and cross-origin traffic pass straight through.
  // POST/PUT/PATCH/DELETE stay network-driven; nothing is queued or replayed,
  // which would be unsafe against an API with approval chains and conditional
  // updates (a replayed approval could act on a record that has since moved).
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Rule 2 — authenticated and analytics traffic is not ours to see.
  if (isNeverCacheable(url)) return;

  // Rule 3 — static assets, cache-first. Content hashing makes this safe: a
  // changed file has a changed URL, so a hit is never stale.
  if (isHashedStatic(url)) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(STATIC_CACHE);
        const hit = await cache.match(request);
        if (hit) return hit;
        try {
          const response = await fetch(request);
          // Only store complete, successful, same-origin responses. An opaque
          // or partial response in the cache is a silent breakage later.
          if (response.ok && response.type === "basic") {
            cache.put(request, response.clone());
          }
          return response;
        } catch (error) {
          // Nothing cached and no network: let the failure surface. A blank
          // stylesheet or script would be worse than a visible error.
          throw error;
        }
      })(),
    );
    return;
  }

  // Rule 4 — navigations. Always from the network, because the document is
  // authenticated and personal. The cache is only ever a fallback, and only
  // ever the generic offline page — never the last page this user visited.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          return await fetch(request);
        } catch {
          const cache = await caches.open(SHELL_CACHE);
          const offline = await cache.match(OFFLINE_URL);
          if (offline) return offline;
          return new Response(
            "You are offline, and the offline page is unavailable.",
            {
              status: 503,
              headers: { "Content-Type": "text/plain; charset=utf-8" },
            },
          );
        }
      })(),
    );
    return;
  }

  // Everything else: straight to the network, uncached.
});


/* ══ Web Push (Phase 6) ═══════════════════════════════════════════════

   Added without changing anything above: the caching rules and their
   boundaries are untouched.

   Two rules govern this section:

     1. TRUST NOTHING IN THE PAYLOAD. It arrives from the network. A malformed
        body must not throw inside the handler (which would leave the user with
        the browser's generic "This site has been updated in the background"),
        and a URL in it must never be able to send the user off-origin.
     2. NEVER OPEN A SECOND WINDOW when one is already there. Focusing the
        existing window and navigating it is what people expect; opening a
        third copy of the intranet is what they complain about.                */

/** The shape we send. Anything else is treated as absent. */
function readPushPayload(event) {
  const fallback = {
    title: "Manut",
    body: "You have a new notification.",
    url: "/dashboard",
    tag: undefined,
    notificationId: undefined,
  };

  if (!event.data) return fallback;

  let raw;
  try {
    raw = event.data.json();
  } catch {
    // Not JSON — take it as a plain body rather than dropping the notification.
    try {
      const text = event.data.text();
      return text ? { ...fallback, body: text } : fallback;
    } catch {
      return fallback;
    }
  }

  if (!raw || typeof raw !== "object") return fallback;

  return {
    title: typeof raw.title === "string" && raw.title ? raw.title : fallback.title,
    body: typeof raw.body === "string" && raw.body ? raw.body : fallback.body,
    url: safeTargetPath(raw.url) ?? fallback.url,
    tag: typeof raw.tag === "string" ? raw.tag : undefined,
    notificationId:
      typeof raw.notificationId === "string" ? raw.notificationId : undefined,
  };
}

/**
 * Accepts only a same-origin, root-relative path.
 *
 * This is the security boundary for notification clicks. The server already
 * refuses to send anything else, but a service worker must not depend on that:
 * anything that reaches `clients.openWindow()` unchecked is an open redirect
 * with a notification as the lure. Mirrors `safeRedirectTarget()` in the web app
 * and `isSafeNotificationUrl()` in the API.
 *
 * Query strings and fragments are preserved — a deep link like
 * `/projects?view=pending` must survive.
 */
function safeTargetPath(value) {
  if (typeof value !== "string" || value.length === 0) return null;
  if (!value.startsWith("/")) return null;
  if (value.startsWith("//")) return null;
  if (value.startsWith("/\\")) return null;
  return value;
}

self.addEventListener("push", (event) => {
  const payload = readPushPayload(event);

  event.waitUntil(
    (async () => {
      // If a window is already focused, the in-app notification bell is
      // showing this already — a system notification on top of it is noise.
      // See "Foreground vs background" in the Phase 6 document.
      const windows = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });
      const focused = windows.some((client) => client.focused);

      if (focused) {
        // Tell the open page instead, so it can refresh its badge.
        for (const client of windows) {
          client.postMessage({
            type: "PUSH_RECEIVED",
            notificationId: payload.notificationId,
            url: payload.url,
          });
        }
        return;
      }

      await self.registration.showNotification(payload.title, {
        body: payload.body,
        icon: "/icons/icon-192.png",
        badge: "/icons/icon-192.png",
        // Collapses repeats of the same underlying item rather than stacking.
        tag: payload.tag || payload.notificationId || undefined,
        renotify: Boolean(payload.tag || payload.notificationId),
        data: { url: payload.url, notificationId: payload.notificationId },
      });
    })(),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const target = safeTargetPath(event.notification.data?.url) ?? "/dashboard";

  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });

      // Reuse a window we already own rather than opening another copy.
      for (const client of windows) {
        const sameOrigin = new URL(client.url).origin === self.location.origin;
        if (sameOrigin && "navigate" in client) {
          await client.focus();
          // `navigate` can reject if the client is in an odd state; focusing is
          // still better than nothing, so the failure is swallowed.
          try {
            await client.navigate(target);
          } catch {
            /* focused but could not navigate — the user is at least in the app */
          }
          return;
        }
      }

      // Nothing open: start at the target. Authentication is the app's own
      // concern — an unauthenticated visit lands on sign-in and returns here
      // afterwards through the existing redirect handling.
      await self.clients.openWindow(target);
    })(),
  );
});
